    fun getByCategory(category: String): List<PronunciationItem> {
        return when (category.lowercase()) {
            "word", "words" -> words
            "idiom", "idioms" -> idioms
            "sentence", "sentences" -> sentences
            else -> emptyList()
        }
    }
